alter table public.support_tickets add column if not exists department text not null default 'general', add column if not exists first_response_due_at timestamptz, add column if not exists resolution_due_at timestamptz, add column if not exists first_responded_at timestamptz, add column if not exists escalated_at timestamptz;
drop policy if exists support_tickets_update_agent on public.support_tickets;
create policy support_tickets_update_agent on public.support_tickets for update to authenticated using(exists(select 1 from public.support_agents a where a.user_id=(select auth.uid()) and a.is_active) and (assigned_agent_id is null or assigned_agent_id=(select auth.uid()))) with check(exists(select 1 from public.support_agents a where a.user_id=(select auth.uid()) and a.is_active) and assigned_agent_id=(select auth.uid()));
create policy support_agents_admin_manage on public.support_agents for all to authenticated using(public.is_super_admin((select auth.uid()))) with check(public.is_super_admin((select auth.uid())));
grant insert,update,delete on public.support_agents to authenticated;
create or replace function public.touch_support_ticket_on_message() returns trigger language plpgsql security definer set search_path to 'public','pg_temp' as $function$ declare v_agent boolean; begin select exists(select 1 from public.support_agents a where a.user_id=new.sender_id and a.is_active) into v_agent; update public.support_tickets set last_message_at=now(),updated_at=now(),first_responded_at=case when v_agent and first_responded_at is null and not new.is_internal then now() else first_responded_at end,status=case when new.is_internal then status when v_agent then 'awaiting_user' else 'awaiting_support' end where id=new.ticket_id; return new; end;$function$;
revoke all on function public.touch_support_ticket_on_message() from public,anon,authenticated;
drop trigger if exists support_message_touch_ticket on public.support_messages;
create trigger support_message_touch_ticket after insert on public.support_messages for each row execute function public.touch_support_ticket_on_message();
